---@class CatAI
local CatAI = Class('CatAI')

function CatAI:__init()
    self.agent = nil
    self.animator = nil
    self.count = 0
    self.isFat = false
    self.co = nil
    self.isStart = true
    self.isRun = false
    self.playerCatId = nil ---服务器数据
    self.isFirst = true ---第一次到达终点后开始防止卡住位移
    self.isFirstCount = 0
    self.lastX = nil       ---记录移动判断是否卡住
    self.lastXCount = 0
    self.MoveState = 1   --- 0停止待机  1正常行走  2需要重新寻找目标,然后正常行走
    self.transform = nil
    self.catType = 0 ---猫种类型
    self.isPlayingDraggingSe = false --- 是否正在播放拖拽音效
end

function CatAI:__delete()
    self.agent = nil
    self.animator = nil
    self.isStart = false
    self.isMoving = false
    self.isFat = false
    self.count = 0
    self.co = nil
    self.playerCatId = nil
    self.isFirst = nil
    self.lastX = nil
    self.lastXCount = nil
    self.transform = nil
    self.resetPath = nil
    self.isRun = false
    self.catType = 0 ---猫种类型
end

function CatAI:AddListener()
    self.__EventCatHouseTimeChange = Events.AddListener(CatHouseCatFatOrRecoverySwitchEventName, Bind(self, self.OnEventCatHouseTimeChange))
end
function CatAI:RemoveListener()
    if self.__EventCatHouseTimeChange then
        Events.RemoveListener(CatHouseCatFatOrRecoverySwitchEventName, self.__EventCatHouseTimeChange)
    end
    self.__EventCatHouseTimeChange = nil
end

function CatAI:Awake()
    self.transform = self.controller.transform
    self:AddListener()
    ---@type UnityEngine.AI.NavMeshAgent
    local agent = kTool.GetOrAddComponent(self.controller.gameObject, typeof(NavMeshAgent))
    agent.acceleration = acceleration
    agent.speed = speed
    agent.angularSpeed = angularSpeed
    agent.radius = radius
    agent.height = height
    self.agent = agent
    self.animator = kTool.GetComponent(self.controller.gameObject, typeof(NamedAnimancerComponent))
end


local function RandomTargetPosition()
    local x = Random.Range(MIN_X, MAX_X)
    local z = Random.Range(MIN_Z, MAX_Z)
    return Vector3(x * 0.01, 0, z * 0.01)
end

