--停止移动 播放休息动画
function CatAI:StopMove()
    self.MoveState = 0
    self.animator:TryPlay(AnimationState.Rest, 0.5)
    self.lastX = nil
    self.lastXCount = 0
    self:SetDestination(self.agent.transform.position)
end

function CatAI:StartRandomMove()
    self.MoveState = 1
    local target = RandomTargetPosition()
    self.agent.transform:LookAt(target)
    self:SetDestination(target)
    --self.agent:SetDestination(target)
    self.animator:TryPlay(AnimationState.Walk, 0.3)
end

function CatAI:OnEnable()
    self.isStart = true
    self.co = self.controller:StartCoroutine(util.cs_generator(function()
        ---@type UnityEngine.Transform
        local transform = self.controller.transform
        while self.isStart and self.agent.isActiveAndEnabled do
            ---执行寻路的逻辑
            if self.MoveState == 1 and self.agent.remainingDistance == 0 and not self.agent.hasPath then
                ---不存在新的路径
                if self.count >= JumpMax then
                    local target = JumpPoints[1]
                    transform:LookAt(target)
                    self:SetDestination(target)
                    --self.agent:SetDestination(target)
                    self.animator:TryPlay(AnimationState.Walk, 0.3)
                    self.count = 0
                else
                    self:StartRandomMove()
                end
                --print('--->>>', self.agent:GetPathRemainingDistance(), self.agent.hasPath)
            end
            ---未准备好的情况下等待
            while not self:IsValidAgent() do
                cs_coroutine.yield_return(Yielders.EndOfFrame)
            end
            if self.MoveState == 2 then
                self:StopMove()
                self:SetRunStatus(false)
                ---休息下
                coroutine.yield(Yielders.GetWaitForSeconds(RestTime))--Random.Range(1,5) ))
                self:StartRandomMove()
                coroutine.yield(Yielders.EndOfFrame)
            elseif self.MoveState == 3 then ---猫要跑开
                self:SetAgentSpeed(runSpeed)
                self.animator:TryPlay(AnimationState.Run, 0.1)
                coroutine.yield(Yielders.GetWaitForSeconds(2))
                self:SetAgentSpeed(speed)
                self.animator:TryPlay(AnimationState.Walk, 0.3)
                self:SetRunStatus(false)
                self.MoveState = 1
                ---是否休息下
            elseif self.MoveState == 1 and  self.agent.remainingDistance < 0.008  then
                self.animator:TryPlay(AnimationState.Rest, 0.5)
                self:SetRunStatus(false)
                ---是否休息下
                coroutine.yield(Yielders.GetWaitForSeconds(RestTime))
                self.count = self.count + 5
                self.animator:TryPlay(AnimationState.Walk, 0.3)
                self.MoveState = 1
            end
            cs_coroutine.yield_return(Yielders.EndOfFrame)
        end
    end))
end

function CatAI:SetAgentSpeed(speed)
    self.agent.speed = speed
end

--每次判定计时
function CatAI:IsValidAgent()
    if self.MoveState == 0 then
        return true
    end
    if self.isFirst then
        self.isFirstCount =   self.isFirstCount + 1
        if self.isFirstCount > 200 then
            self.isFirst = false
        end
        return self.agent:IsValidAgent()
    end
    if self.agent:IsValidAgent() then
        if  self.lastX == nil  then
            self.lastX = self.agent.transform.position.x
        else
            self.lastXCount = self.lastXCount + 1
            --每20帧做一次判定
            if self.lastXCount > 20 then
                local dis=   self.agent.transform.position.x - self.lastX
                self.lastX = nil
                self.lastXCount = 0
                if dis<0.002 and dis>-0.002 then
                    self.MoveState = 2
                    return false
                end
            end
        end
        return true
    else
        self.lastX = nil
        self.lastXCount = 0
        return false
    end
end

function CatAI:StopTapAction()
    ---暂停
    self.isStart = false
    self.lastX = nil
    self.lastXCount = 0
    local pos = self.agent.transform.position
    self:SetDestination(pos)
    --self.agent:SetDestination(pos)
    self.agent.enabled = false
    self:OnDisable()
    self.animator:TryPlay(AnimationState.BeforeCatch, 0.1)
end

--- RunAway  人在猫后面时 猫要跑开
function CatAI:RunAway()
    self:SetRunStatus(true)
    self.MoveState = 3
end

---StartDrag
---开始拖动的逻辑
function CatAI:StartDrag()
    self.animator:TryPlay(AnimationState.Catching, 0.1)
    CS.DynamicBone.IsEnabled = true
    CriWareUtils.PlaySe(UISheets.UI_Menu.path, UISheets.UI_Menu.ui_zhuaqi)
end

---OnDragging
---移动中的逻辑
function CatAI:OnDragging(position)
    if self.transform then
        local y = position.y
        local x = position.x
        local z = position.z
        if y >= 1.55 then
            position.y = 1.55
        elseif y <= -0.02 then
            position.y = -0.02
        end
        if x >= MAX_X * 0.01 then
            position.x = MAX_X * 0.01
        elseif x < MIN_X * 0.01 then
            position.x = MIN_X * 0.01
        end
        if z >= MAX_Z * 0.01 then
            position.z = MAX_Z * 0.01
        elseif z < MIN_Z * 0.01 then
            position.z = MIN_Z * 0.01
        end
        self.transform.localPosition = position
        self:PlayDraggingSe()

    end
end

function CatAI:PlayDraggingSe()
    if self.isPlayingDraggingSe then
        return
    end
    self.isPlayingDraggingSe = true
    if self.bornType == BornType.Baby then
        CriWareUtils.PlaySe(UISheets.UI_Menu.path, UISheets.UI_Menu.ui_tingliu_weichengnian)
    elseif self.bornType == BornType.Adult then
        CriWareUtils.PlaySe(UISheets.UI_Menu.path, UISheets.UI_Menu.ui_tingliu_chengnian)
    end
end

function CatAI:StopDraggingSe()
    if self.bornType == BornType.Baby then
        CriWareUtils.Stop(UISheets.UI_Menu.path, UISheets.UI_Menu.ui_tingliu_weichengnian)
    elseif self.bornType == BornType.Adult then
        CriWareUtils.Stop(UISheets.UI_Menu.path, UISheets.UI_Menu.ui_tingliu_chengnian)
    end
end


function CatAI:GetDraggingOffset()
    if self.bornType == BornType.Baby then
        return 0.46
    elseif self.bornType == BornType.Adult then
        return 0.4
    end
end
---Restart
---拖动完所后重新启动逻辑
function CatAI:DragEnd()
    CS.DynamicBone.IsEnabled = false
    self.animator:TryPlay(AnimationState.AfterCatch, 0.1)
    if self.transform then
        local position = self.transform.localPosition
        self.transform.localPosition = Vector3.New(position.x, 0, position.z)
    end
    self.isStart = true
    self.agent.enabled = true
    self:OnEnable()
    self:StartRandomMove()
    self:StopDraggingSe()
    CriWareUtils.PlaySe(UISheets.UI_Menu.path, UISheets.UI_Menu.ui_fangxia)
    self.isPlayingDraggingSe = false
end

function CatAI:StopCo()
    self.isStart = false
    if self.co then
        self.controller:StopCoroutine(self.co)
        --cs_coroutine.stop(self.co)
    end
    self.co = nil
end

function CatAI:SetRunStatus(status)
    self.isRun = status
end

function CatAI:GetRunStatus()
    return self.isRun
end

function CatAI:OnDestroy()
    self.transform = nil
    self:RemoveListener()
    ---@type Engine.Lib.BehaviourAction
    local behaviourAction = kTool.GetOrAddComponent(self.controller.gameObject, typeof(BehaviourAction))
    if behaviourAction then
        behaviourAction.OnDisableAction = nil
        behaviourAction.OnEnableAction = nil
    end
    self:StopCo()
    self.agent = nil
    self.animator = nil
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return CatAI